CREATE TABLE tenant (id UUID PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE application_user (id UUID PRIMARY KEY, username VARCHAR(200) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(32) NOT NULL, tenant_id UUID REFERENCES tenant(id), enabled BOOLEAN NOT NULL DEFAULT TRUE);
ALTER TABLE application_user ADD CONSTRAINT ck_user_tenant_role CHECK ((role='PLATFORM_ADMIN' AND tenant_id IS NULL) OR (role='TENANT_ADMIN' AND tenant_id IS NOT NULL));